import { createChart } from '../../test/ut/core/utHelper';
import { EChartsType } from '@/src/echarts';
import Parallel from '@/src/coord/parallel/Parallel';

describe('parallel_axis_extent', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function getAxisExtent(chart: EChartsType, dim: string): number[] {
        const ecModel = (chart as any).getModel();
        const parallelModel = ecModel.getComponent('parallel', 0);
        const coordSys = parallelModel.coordinateSystem as Parallel;
        return coordSys.getAxis(dim as any).scale.getExtent();
    }

    it('extent_should_cover_subsequent_series_with_larger_values', function () {
        chart.setOption({
            parallelAxis: [
                { dim: 0, name: 'A' },
                { dim: 1, name: 'B' }
            ],
            series: [
                {
                    type: 'parallel',
                    data: [[1, 10], [2, 20]]
                },
                {
                    type: 'parallel',
                    data: [[50, 500], [100, 1000]]
                }
            ]
        });

        const extent0 = getAxisExtent(chart, 'dim0');
        const extent1 = getAxisExtent(chart, 'dim1');

        expect(extent0[0]).toBeLessThanOrEqual(1);
        expect(extent0[1]).toBeGreaterThanOrEqual(100);
        expect(extent1[0]).toBeLessThanOrEqual(10);
        expect(extent1[1]).toBeGreaterThanOrEqual(1000);
    });

    it('extent_should_cover_all_series_regardless_of_order', function () {
        chart.setOption({
            parallelAxis: [
                { dim: 0, name: 'A' }
            ],
            series: [
                {
                    type: 'parallel',
                    data: [[500], [1000]]
                },
                {
                    type: 'parallel',
                    data: [[1], [2]]
                }
            ]
        });

        const extent0 = getAxisExtent(chart, 'dim0');
        expect(extent0[0]).toBeLessThanOrEqual(1);
        expect(extent0[1]).toBeGreaterThanOrEqual(1000);
    });
});
